import {
  boolean,
  integer,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

import { LEAD_STATUSES } from "@/lib/lead-status";

// SOT:db-schema
// WHAT: Drizzle schema — the single source of truth for all entity types.
// WHY:  Leads, notes, and history events; types are derived, never hand-written.
// HOW:  Consumed only via src/db/client.ts inside src/services/*.
// WHERE: Migrations generated by Drizzle Kit into /drizzle.

export const leadStatusEnum = pgEnum("lead_status", LEAD_STATUSES);

export const leadEventTypeEnum = pgEnum("lead_event_type", [
  "import",
  "status_change",
  "note",
  "edit",
  "photo",
]);

export const leads = pgTable("leads", {
  id: uuid("id").primaryKey().defaultRandom(),
  externalId: text("external_id"),
  source: text("source").notNull(),
  leadDate: timestamp("lead_date", { withTimezone: true }),
  customerName: text("customer_name").notNull().default(""),
  phone: text("phone").notNull().default(""),
  email: text("email").notNull().default(""),
  brandModel: text("brand_model").notNull().default(""),
  regNo: text("reg_no").notNull().default(""),
  year: integer("year"),
  photos: text("photos").array().notNull().default([]),
  kmDriven: integer("km_driven"),
  owners: integer("owners"),
  location: text("location").notNull().default(""),
  expectedPrice: integer("expected_price"),
  status: leadStatusEnum("status").notNull().default("new_lead"),
  isDuplicate: boolean("is_duplicate").notNull().default(false),
  isFeatured: boolean("is_featured").notNull().default(false),
  isFavorite: boolean("is_favorite").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

export const leadNotes = pgTable("lead_notes", {
  id: uuid("id").primaryKey().defaultRandom(),
  leadId: uuid("lead_id")
    .notNull()
    .references(() => leads.id, { onDelete: "cascade" }),
  text: text("text").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

export const leadEvents = pgTable("lead_events", {
  id: uuid("id").primaryKey().defaultRandom(),
  leadId: uuid("lead_id")
    .notNull()
    .references(() => leads.id, { onDelete: "cascade" }),
  type: leadEventTypeEnum("type").notNull(),
  fromStatus: leadStatusEnum("from_status"),
  toStatus: leadStatusEnum("to_status"),
  detail: text("detail"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

export type Lead = typeof leads.$inferSelect;
export type NewLead = typeof leads.$inferInsert;
export type LeadNote = typeof leadNotes.$inferSelect;
export type LeadEvent = typeof leadEvents.$inferSelect;
